"""Conformance arm 2 — __file__-relative data load from inside the image.

The bundled sample table is read through a path derived from THIS file's
__file__ in the mounted context (the classic python data-file pattern).
The read must come back with the exact rows the feedstock authored — a
byte count + a sha256, asserted against the values recorded at build
time (authored content, so the constants are stable).
"""

import hashlib
import os
import sys

_site = os.path.dirname(os.path.dirname(os.path.dirname(os.path.abspath(__file__))))
if _site not in sys.path:
    sys.path.insert(0, _site)

# The table rides beside the toolkit package: site-packages/pydata_toolkit/
# data/rivers.csv, two levels up from this conformance dir. Lexical
# os.path only — no realpath re-rooting.
DATA = os.path.join(
    os.path.dirname(os.path.dirname(os.path.abspath(__file__))), "data", "rivers.csv"
)

# Authored-content constants (tools/build asserts them against the staged
# tree, so a drifted data file fails at BUILD time, not here).
WANT_ROWS = 28
WANT_SHA256 = "@@RIVERS_SHA256@@"


def main():
    print("__file__: %s" % os.path.abspath(__file__))
    print("data path (__file__-derived): %s" % DATA)
    with open(DATA, "rb") as handle:
        blob = handle.read()
    digest = hashlib.sha256(blob).hexdigest()
    rows = blob.decode("utf-8").strip().splitlines()[1:]  # drop the header
    print("read %d data rows (%d bytes, sha256 %s)" % (len(rows), len(blob), digest))
    if digest != WANT_SHA256:
        sys.stderr.write("arm2: bundled CSV digest %s != %s\n" % (digest, WANT_SHA256))
        return 1
    if len(rows) != WANT_ROWS:
        sys.stderr.write("arm2: %d rows != %d\n" % (len(rows), WANT_ROWS))
        return 1
    first = rows[0].split(",")
    print("first row: %s" % first)
    print("ARM2-OK")
    return 0


if __name__ == "__main__":
    sys.exit(main())
